def book(copies, side, user, mode):
    """The link is down: each side only sees its own copy. New York owns the seat."""
    if mode == "CP" and side != "NY":
        return "error, try again later"
    copies[side] = user
    return "booked"

for mode in ["CP", "AP"]:
    seat = {"NY": None, "London": None}
    print(mode, "Ana:", book(seat, "NY", "Ana", mode))
    print(mode, "Bob:", book(seat, "London", "Bob", mode))
    print(mode, "copies:", seat)

